// The slice of the generated Mojo WebUI TS bindings that MojoBridge calls (Chromium build). The bindings are
// generated by Chromium's mojom() GN template from chromium/clu/common/mojom/*.mojom and served by the browser at
// `/mojom/<file>.mojom-webui.js` on both Clu WebUIs; they do not exist in this repo's build, so they load at runtime.
//
// Shapes the generated code has (Chromium 158, mojo/public/tools/bindings/generators/mojom_ts_generator.py):
//   - `<Iface>.getRemote()` binds a remote through the frame's BrowserInterfaceBroker.
//   - Methods are lowerCamelCase and resolve `{ result: CallResult }`.
//   - Struct fields are lowerCamelCase of the mojom snake_case names; enums are numbers; a union is an object with one
//     field set; nullable is `T | null`; `map<string, T>` is a plain object.
//   - `StateObserverCallbackRouter` exposes `onState.addListener(fn)` and `$.bindNewPipeAndPassRemote()`.

/** CallResult from bridge.mojom: exactly one of the two fields is set. */
export interface MojoCallResult {
  valueJson?: string | null
  error?: { code: number; message: string | null; reason: string | null } | null
}
/** SurfaceInfo from bridge.mojom. `layer` is a SurfaceLayer value (0 top, 1 under-peek, 2 passive). */
export interface MojoSurfaceInfo { windowId: string | null; layer: number | null; slot: number | null; contractVersion: string }

export type MojoMethod = (input?: unknown) => Promise<{ result: MojoCallResult }>
export type MojoRemote = Record<string, MojoMethod | undefined>

export interface MojoBindings {
  /** `<iface>.getRemote()` from `<file>.mojom-webui.js`. */
  getRemote(file: string, iface: string): MojoRemote
  /** StateSource.getRemote().subscribe(router.$.bindNewPipeAndPassRemote()), with `onMessage` on router.onState. */
  subscribeState(onMessage: (messageJson: string) => void): Promise<{ info: MojoSurfaceInfo }>
}

interface GeneratedInterface { getRemote(): unknown }
interface GeneratedRouter {
  onState: { addListener(fn: (messageJson: string) => void): number }
  $: { bindNewPipeAndPassRemote(): unknown }
}
type GeneratedModule = Record<string, unknown>

/** Loads the generated modules from this WebUI's origin. `files` comes from MOJO_MODULES (mojo-wire.gen.ts). */
export async function loadWebUiBindings(files: readonly string[], base = new URL('/mojom/', window.location.origin)): Promise<MojoBindings> {
  const modules = new Map<string, GeneratedModule>()
  await Promise.all(
    files.map(async (file) => {
      const url = new URL(`${file}.mojom-webui.js`, base).href
      modules.set(file, (await import(/* @vite-ignore */ url)) as GeneratedModule)
    })
  )
  const exported = <T>(file: string, name: string): T => {
    const value = modules.get(file)?.[name]
    if (!value) throw new Error(`${file}.mojom-webui.js has no export ${name}`)
    return value as T
  }
  return {
    getRemote: (file, iface) => exported<GeneratedInterface>(file, iface).getRemote() as MojoRemote,
    subscribeState(onMessage) {
      const Router = exported<new () => GeneratedRouter>('bridge', 'StateObserverCallbackRouter')
      const source = exported<GeneratedInterface>('bridge', 'StateSource').getRemote() as { subscribe(observer: unknown): Promise<{ info: MojoSurfaceInfo }> }
      const router = new Router()
      router.onState.addListener(onMessage)
      return source.subscribe(router.$.bindNewPipeAndPassRemote())
    }
  }
}
